package io.github.turbopro.ism.safety;
import io.github.turbopro.ism.common.api.ApiResponse;import io.github.turbopro.ism.common.infrastructure.authorization.RequiresPermission;import io.github.turbopro.ism.common.infrastructure.web.ApiResponseFactory;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated@RestController@RequestMapping("/api/safety/issues")public class SafetyIssueController{private final SafetyIssueService service;private final ApiResponseFactory responses;public SafetyIssueController(SafetyIssueService s,ApiResponseFactory r){service=s;responses=r;}@GetMapping@RequiresPermission("safety:issue:view")ApiResponse<SafetyIssueModels.Page>list(@RequestParam(defaultValue="")@Size(max=100)String keyword,@RequestParam(defaultValue="")String status,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return responses.success(service.list(keyword,status,page,size));}@PostMapping@RequiresPermission("safety:issue:create")ApiResponse<SafetyIssueModels.View>create(@Valid@RequestBody SafetyIssueModels.Create c){return responses.success(service.create(c));}@PostMapping("/{id}/rectification")@RequiresPermission("safety:issue:rectify")ApiResponse<SafetyIssueModels.View>rectify(@PathVariable long id,@Valid@RequestBody SafetyIssueModels.Rectify c){return responses.success(service.rectify(id,c));}@PostMapping("/{id}/verification")@RequiresPermission("safety:issue:verify")ApiResponse<SafetyIssueModels.View>verify(@PathVariable long id,@Valid@RequestBody SafetyIssueModels.Verify c){return responses.success(service.verify(id,c));}}
